def chip_poly(w, h, cut=10):
    """削角芯片形状（左上 + 右下 45° 切角）"""
    p = QtGui.QPainterPath()
    p.moveTo(cut, 0.5)
    p.lineTo(w - 0.5, 0.5)
    p.lineTo(w - 0.5, h - cut)
    p.lineTo(w - cut, h - 0.5)
    p.lineTo(0.5, h - 0.5)
    p.lineTo(0.5, cut)
    p.closeSubpath()
    return p


class ChipButton(QtWidgets.QAbstractButton):
    """削角芯片按钮 —— 悬停时内部有青/黄填充扫描（局部动效）"""

    STYLES = {
        'primary': (C_YEL, '#0A0A0C', C_YEL),
        'danger': (C_RED, '#FFFFFF', C_RED),
        'safe': (C_OK, '#04210F', C_OK),
        'ghost': (None, None, C_LINE2),
    }

    def __init__(self, text, variant='ghost', cut=10, parent=None):
        super(ChipButton, self).__init__(parent)
        self.setText(text)
        self.variant = variant
        self.cut = cut
        self._hv = 0.0
        self.setMinimumHeight(36)
        self.setCursor(QtCore.Qt.PointingHandCursor)
        f = fnt(F_UI, 11)
        self.setFont(f)
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(50)                      # 悬停填充 20fps（原 30fps）
        self._t.setTimerType(QtCore.Qt.CoarseTimer)

    def _tick(self):
        tgt = 1.0 if (self.underMouse() and self.isEnabled()) else 0.0
        if not FX.on():
            if self._hv != tgt:
                self._hv = tgt
                self.update()
            return
        if abs(self._hv - tgt) > 0.012:
            self._hv += (tgt - self._hv) * 0.22
            self.update()

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.Antialiasing, True)
        w, h = self.width(), self.height()
        fill, txt, border = self.STYLES.get(self.variant, self.STYLES['ghost'])
        path = chip_poly(w, h, self.cut)
        enabled = self.isEnabled()
        p.setPen(QtCore.Qt.NoPen)
        if fill:
            p.setBrush(QtGui.QBrush(QtGui.QColor(fill if enabled else C_LINE)))
            p.drawPath(path)
        else:
            p.setBrush(QtGui.QBrush(QtGui.QColor(C_BG2 if enabled else '#101113')))
            p.drawPath(path)
            if self._hv > 0.01 and enabled:
                p.save()
                p.setClipPath(path)
                p.setBrush(QtGui.QBrush(QtGui.QColor(0, 229, 255, int(38 * self._hv))))
                p.drawRect(0, 0, int(w * self._hv), h)
                p.restore()
        p.setBrush(QtCore.Qt.NoBrush)
        bc = QtGui.QColor(border)
        if self._hv > 0.5 and enabled and self.variant == 'ghost':
            bc = QtGui.QColor(C_CYA)
        if not enabled:
            bc = QtGui.QColor(C_LINE)
        p.setPen(QtGui.QPen(bc, 1))
        p.drawPath(path)
        if self._hv > 0.05 and enabled and self.variant != 'ghost':
            p.setPen(QtGui.QPen(QtGui.QColor(255, 255, 255, int(120 * self._hv)), 1))
            p.drawPath(path)
        col = QtGui.QColor(txt if (txt and enabled) else (C_TX if enabled else '#4A5158'))
        p.setPen(QtGui.QPen(col, 1))
        f = fnt(F_UI, 11)
        if self.variant in ('primary', 'danger', 'safe'):
            f.setBold(True)
        p.setFont(f)
        p.drawText(QtCore.QRect(0, 0, w, h), QtCore.Qt.AlignCenter, self.text())
        p.end()


class HazardBar(QtWidgets.QWidget):
    """黄黑斜纹警示条（静态构件）"""
    def __init__(self, h=8, parent=None):
        super(HazardBar, self).__init__(parent)
        self.setFixedHeight(h)

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor('#0A0A0C'))
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(C_YEL)))
        x = -h
        while x < w + h:
            p.drawPolygon(QtGui.QPolygon([
                QtCore.QPoint(x, h), QtCore.QPoint(x + 7, h),
                QtCore.QPoint(x + 7 + h, 0), QtCore.QPoint(x + h, 0)]))
            x += 16
        p.end()


class GlitchLabel(QtWidgets.QWidget):
    """主标题：Relic 式红青通道分离（间歇、局部）"""
    def __init__(self, text, sub=u'', parent=None):
        super(GlitchLabel, self).__init__(parent)
        self.text = text
        self.sub = sub
        self.setFixedHeight(46)
        self.setMinimumWidth(440)
        self._burst = 0
        self._frames = 0
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(60)

    def _tick(self):
        if not FX.on():
            return
        self._frames += 1
        self._burst -= 1
        if self._burst < -70 and random.random() < 0.03:
            self._burst = random.randint(4, 9)
        if self._burst > 0 or self._frames % 90 < 3:
            self.update()

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.Antialiasing, True)
        off = 0
        if FX.on() and self._burst > 0:
            off = random.choice([-3, -2, 2, 3])
        f = fnt(F_TITLE, 17)
        f.setBold(True)
        p.setFont(f)
        p.setPen(QtGui.QPen(QtGui.QColor(C_CYA), 1))
        p.drawText(3 + off, 29, self.text)
        p.setPen(QtGui.QPen(QtGui.QColor(C_RED), 1))
        p.drawText(3 - off, 29, self.text)
        p.setPen(QtGui.QPen(QtGui.QColor('#F2F4F6'), 1))
        p.drawText(3, 29, self.text)
        # 黄色下划芯片
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(C_YEL)))
        tw = p.fontMetrics().width(self.text)
        p.drawPolygon(QtGui.QPolygon([
            QtCore.QPoint(3, 34), QtCore.QPoint(3 + tw - 6, 34),
            QtCore.QPoint(3 + tw - 12, 38), QtCore.QPoint(3, 38)]))
        if self.sub:
            p.setFont(fnt(F_MONO, 8))
            p.setPen(QtGui.QPen(QtGui.QColor(C_TX2), 1))
            p.drawText(5, 45, self.sub)
        p.end()


class StatusDot(QtWidgets.QWidget):
    def __init__(self, size=10, parent=None):
        super(StatusDot, self).__init__(parent)
        self.setFixedSize(size, size)
        self._c = QtGui.QColor(C_TX2)
        self._ph = random.random()
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(95)                      # 呼吸 10fps（原 16fps）
        self._t.setTimerType(QtCore.Qt.CoarseTimer)

    def set_color(self, c):
        self._c = QtGui.QColor(c)
        self.update()

    def _tick(self):
        if FX.on():
            self._ph = (self._ph + 0.05) % 1.0
            self.update()

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.Antialiasing, False)
        s = self.width()
        a = 130 + int(125 * abs(math.sin(self._ph * 3.14159)))
        c = QtGui.QColor(self._c)
        c.setAlpha(a if FX.on() else 255)
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(self._c.red(), self._c.green(),
                                             self._c.blue(), 55)))
        p.drawRect(0, 0, s, s)
        p.setBrush(QtGui.QBrush(c))
        p.drawRect(2, 2, s - 4, s - 4)
        p.end()


class BlockSlider(QtWidgets.QSlider):
    """方块段电平条（夜之城血条风）"""
    BLOCKS = 24

    def __init__(self, lo, hi, parent=None):
        super(BlockSlider, self).__init__(QtCore.Qt.Horizontal, parent)
        self.setRange(lo, hi)
        self.setFixedHeight(20)
        self.setCursor(QtCore.Qt.PointingHandCursor)
        self.setFocusPolicy(QtCore.Qt.StrongFocus)      # 允许键盘微调
        self._last_key = 0.0

    def keyPressEvent(self, e):
        """← ↓ 步退 / → ↑ 步进（Shift = 10 步）；PgUp/PgDn 十步；
           Home 或空格 = 归零；End = 置最大
           ★ 三重保险：① 未解锁不生效 ② 忽略长按自动重复（X 默认 33 次/秒）
             ③ 速率上限约 8 次/秒 —— 防止按键卡住时狂发底盘指令"""
        if e.isAutoRepeat():
            return
        if not KB_ARMED[0]:
            return
        now = time.time()
        if now - self._last_key < 0.05:      # 宽松上限 ~20 次/秒
            return
        self._last_key = now
        k = e.key()
        stp = 10 if (e.modifiers() & QtCore.Qt.ShiftModifier) else 1
        lo, hi, v = self.minimum(), self.maximum(), self.value()
        if k in (QtCore.Qt.Key_Left, QtCore.Qt.Key_Down):
            self.setValue(max(lo, v - stp))
        elif k in (QtCore.Qt.Key_Right, QtCore.Qt.Key_Up):
            self.setValue(min(hi, v + stp))
        elif k == QtCore.Qt.Key_PageDown:
            self.setValue(max(lo, v - 10))
        elif k == QtCore.Qt.Key_PageUp:
            self.setValue(min(hi, v + 10))
        elif k in (QtCore.Qt.Key_Home, QtCore.Qt.Key_Space):
            self.setValue(lo)
        elif k == QtCore.Qt.Key_End:
            self.setValue(hi)
        else:
            super(BlockSlider, self).keyPressEvent(e)

    def _fill_ratio(self):
        lo, hi = self.minimum(), self.maximum()
        return 0.0 if hi == lo else float(self.value() - lo) / (hi - lo)

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.Antialiasing, False)
        w, h = self.width(), self.height()
        y = (h - 10) / 2
        gap = 2
        bw = (w - gap * (self.BLOCKS - 1)) / float(self.BLOCKS)
        ratio = self._fill_ratio()
        n_on = int(round(ratio * self.BLOCKS))
        for i in range(self.BLOCKS):
            x = int(i * (bw + gap))
            r = QtCore.QRect(x, y, max(2, int(bw)), 10)
            if i < n_on:
                p.fillRect(r, QtGui.QColor(C_YEL))
            else:
                p.fillRect(r, QtGui.QColor('#24282C'))
        # 右侧削角手柄指示
        hx = int(ratio * (w - 6))
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(C_CYA)))
        p.drawPolygon(QtGui.QPolygon([
            QtCore.QPoint(hx, y - 3), QtCore.QPoint(hx + 6, y - 3),
            QtCore.QPoint(hx + 6, y + 13), QtCore.QPoint(hx, y + 13)]))
        if self.hasFocus():                              # 焦点环：提示可键盘微调
            p.setBrush(QtCore.Qt.NoBrush)
            p.setPen(QtGui.QPen(QtGui.QColor(C_CYA if KB_ARMED[0] else C_YEL), 1))
            p.drawRect(1, 1, w - 3, h - 3)
            p.setPen(QtGui.QPen(QtGui.QColor(C_YEL), 1))
            p.drawLine(1, 1, 7, 1)
            p.drawLine(1, 1, 1, 7)
        p.end()

    def mousePressEvent(self, e):
        if e.button() == QtCore.Qt.LeftButton:
            self._set_from_x(e.x())
        super(BlockSlider, self).mousePressEvent(e)

    def mouseMoveEvent(self, e):
        if e.buttons() & QtCore.Qt.LeftButton:
            self._set_from_x(e.x())
        super(BlockSlider, self).mouseMoveEvent(e)

    def _set_from_x(self, x):
        lo, hi = self.minimum(), self.maximum()
        r = max(0.0, min(1.0, float(x) / max(1, self.width())))
        self.setValue(int(round(lo + r * (hi - lo))))


class Telemetry(QtWidgets.QWidget):
    """顶部遥测条：分块读数（数值就地更新）"""
    def __init__(self, parent=None):
        super(Telemetry, self).__init__(parent)
        self.setFixedHeight(30)
        self.vals = [('LINK', '--'), ('MASTER', '--'), ('NODE', '--'),
                     ('CAM', '--'), ('FPS', '--'), ('UTC', '--')]
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._clock)
        self._t.start(1000)

    def set_val(self, key, val):
        for i, (k, _) in enumerate(self.vals):
            if k == key:
                self.vals[i] = (k, val)
        self.update()

    def _clock(self):
        self.set_val('UTC', time.strftime('%H:%M:%S'))

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor('#0D0E10'))
        f = fnt(F_MONO, 8)
        p.setFont(f)
        x = 10
        for i, (k, v) in enumerate(self.vals):
            p.setPen(QtGui.QPen(QtGui.QColor(C_TX2), 1))
            p.drawText(x, 12, k)
            p.setFont(fnt(F_MONO, 9, QtGui.QFont.Bold))
            p.setPen(QtGui.QPen(QtGui.QColor(C_YEL if i % 2 == 0 else C_CYA), 1))
            p.drawText(x, 25, unicode(v))
            x += max(64, p.fontMetrics().width(unicode(v)) + 26)
            p.setFont(f)
            if i < len(self.vals) - 1:
                p.setPen(QtGui.QPen(QtGui.QColor(C_LINE2), 1))
                p.drawLine(x - 12, 4, x - 12, h - 4)
        p.setPen(QtGui.QPen(QtGui.QColor(C_YEL), 1))
        p.drawLine(0, h - 1, w, h - 1)
        p.end()


class EventStrip(QtWidgets.QWidget):
    """遥测事件条：关键事件从右向左漂移并淡出（数据驱动，仅在条内活动）"""
    LIFE = 50.0

    def __init__(self, parent=None):
        super(EventStrip, self).__init__(parent)
        self.setFixedHeight(26)
        self.events = []
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(60)                      # 事件条 16fps（原 25fps）
        self._t.setTimerType(QtCore.Qt.CoarseTimer)

    def push(self, color, text):
        self.events.append((time.time(), color, text))
        if len(self.events) > 60:
            self.events = self.events[-60:]
        self.update()

    def _tick(self):
        if not self.events:
            return
        now = time.time()
        n0 = len(self.events)
        self.events = [e for e in self.events if now - e[0] < self.LIFE]
        if FX.on() or len(self.events) != n0:
            self.update()

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        w, h = self.width(), self.height()
        p.fillRect(0, 0, w, h, QtGui.QColor('#08090B'))
        p.setPen(QtGui.QPen(QtGui.QColor(C_LINE), 1))
        p.drawRect(0, 0, w - 1, h - 1)
        p.setPen(QtGui.QPen(QtGui.QColor('#1E2228'), 1))
        x = 92
        while x < w:
            p.drawLine(x, h - 5, x, h - 1)
            x += 44
        p.setFont(fnt(F_MONO, 8))
        p.setPen(QtGui.QPen(QtGui.QColor(C_TX2), 1))
        p.drawText(8, 17, u'EVENT LOG')
        p.setPen(QtGui.QPen(QtGui.QColor(C_YEL), 1))
        p.drawLine(78, 6, 78, h - 6)
        now = time.time()
        for (t0, color, text) in self.events:
            age = now - t0
            r = age / self.LIFE
            x = int(w - 14 - r * (w - 110))
            a = int(255 * (1.0 - r * r))
            if a < 14:
                continue
            c = QtGui.QColor(color)
            p.setPen(QtGui.QPen(QtGui.QColor(c.red(), c.green(), c.blue(), a), 2))
            p.drawLine(x, 4, x, h - 5)
            if age < 7.0:
                p.setFont(fnt(F_MONO, 7))
                p.setPen(QtGui.QPen(QtGui.QColor(c.red(), c.green(), c.blue(),
                                                 min(255, a + 70)), 1))
                p.drawText(x + 4, 15, text)
        p.end()


class Panel(QtWidgets.QFrame):
    """削角面板 + 黄色芯片表头 + 角标 + 竖排片假名 + 幽灵编号"""
    HEADER_H = 44

    def __init__(self, module_no, title, ghost=u'', side=u'', parent=None):
        super(Panel, self).__init__(parent)
        self.setObjectName('panel')
        self.module_no = module_no
        self.title = title
        self.ghost = ghost
        self.side = side
        self._blk = 0.0
        self._t = QtCore.QTimer(self)
        self._t.timeout.connect(self._tick)
        self._t.start(82)                      # 表头扫描 12fps（原 20fps）
        self._t.setTimerType(QtCore.Qt.CoarseTimer)
        self.body = QtWidgets.QVBoxLayout(self)
        self.body.setContentsMargins(24, self.HEADER_H + 10, 12, 14)
        self.body.setSpacing(8)

    def _tick(self):
        if not FX.on():
            return
        self._blk = (self._blk + 0.009) % 1.0
        self.update(0, 0, self.width(), self.HEADER_H)

    def paintEvent(self, ev):
        p = QtGui.QPainter(self)
        p.setRenderHint(QtGui.QPainter.Antialiasing, True)
        w, h = self.width(), self.height()
        hh = self.HEADER_H
        cut = 16
        path = chip_poly(w, h, cut)
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(C_BG1)))
        p.drawPath(path)
        # 边框：青
        p.setBrush(QtCore.Qt.NoBrush)
        p.setPen(QtGui.QPen(QtGui.QColor(C_LINE2), 1))
        p.drawPath(path)
        # 削角斜线：黄（夜之城标志性）
        p.setPen(QtGui.QPen(QtGui.QColor(C_YEL), 2))
        p.drawLine(cut, 0, 0, cut)
        p.drawLine(w - 1, h - cut, w - cut, h - 1)
        # 表头
        p.fillRect(2, 2, w - 4, hh, QtGui.QColor('#15171A'))
        p.setPen(QtGui.QPen(QtGui.QColor(C_LINE2), 1))
        p.drawLine(0, hh, w, hh)
        # 黄色芯片（模块编号）
        p.setPen(QtCore.Qt.NoPen)
        p.setBrush(QtGui.QBrush(QtGui.QColor(C_YEL)))
        cw = 92
        p.drawPolygon(QtGui.QPolygon([
            QtCore.QPoint(0, 2), QtCore.QPoint(cw, 2),
            QtCore.QPoint(cw - 12, hh - 2), QtCore.QPoint(0, hh - 2)]))
        p.setPen(QtGui.QPen(QtGui.QColor('#0A0A0C'), 1))
        f = fnt(F_MONO, 8, QtGui.QFont.Bold)
        p.setFont(f)
        p.drawText(QtCore.QRect(10, 2, cw - 26, hh - 2),
                   QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft, self.module_no)
        # 标题
        f2 = fnt(F_UI, 14)
        f2.setBold(True)
        p.setFont(f2)
        p.setPen(QtGui.QPen(QtGui.QColor(C_TX), 1))
        p.drawText(cw + 10, 2, w - cw - 100, hh - 2,
                   QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft, self.title)
        # 幽灵编号
        if self.ghost:
            p.setFont(fnt(F_MONO, 32, QtGui.QFont.Bold))
            p.setPen(QtGui.QPen(QtGui.QColor('#242719'), 1))
            p.drawText(w - 92, 40, self.ghost)
            p.setPen(QtGui.QPen(QtGui.QColor('#33370F'), 1))
            p.drawText(w - 92, 40, self.ghost)
        # 竖排片假名
        if self.side:
            p.save()
            p.translate(14, hh + 18)
            p.rotate(90)
            p.setFont(fnt(F_KANA, 8))
            p.setPen(QtGui.QPen(QtGui.QColor('#4A4F2A'), 1))
            p.drawText(0, 0, self.side)
            p.restore()
        # 表头滑动黄块（夜之城加载芯片）
        if FX.on():
            bw = 90
            bx = int(self._blk * (w + bw)) - bw
            p.save()
            p.setClipRect(0, 2, w, hh)
            g = QtGui.QLinearGradient(bx, 0, bx + bw, 0)
            g.setColorAt(0.0, QtGui.QColor(252, 238, 10, 0))
            g.setColorAt(0.5, QtGui.QColor(252, 238, 10, 70))
            g.setColorAt(1.0, QtGui.QColor(252, 238, 10, 0))
            p.setPen(QtCore.Qt.NoPen)
            p.setBrush(QtGui.QBrush(g))
            p.drawRect(bx, hh - 3, bw, 3)
            p.restore()
        # 底部刻度
        p.setPen(QtGui.QPen(QtGui.QColor('#2E3238'), 1))
        x = 14
        while x < w - 14:
            p.drawLine(x, h - 5, x, h - 3 if (x // 14) % 5 else h - 1)
            x += 14
        p.end()


