class CamView(QtWidgets.QWidget):
    def __init__(self, name, topic, crop=None):
        super(CamView, self).__init__()
        self.cam_name = name
        self.crop = crop          # (起, 止) 比例；四合一全景取其中一路
        self.topic = None
        self.sub = None
        self.frames = 0
        self.last_ts = 0.0
        self.size_txt = ''
        self._pix = None
        self._rgb = None
        self._src_w = 0        # 上次解码的原始宽度（用于选降采样倍数）

        v = QtWidgets.QVBoxLayout(self)
        v.setContentsMargins(0, 0, 0, 0)
        v.setSpacing(3)
        head = QtWidgets.QHBoxLayout()
        head.setSpacing(4)
        lb = QtWidgets.QLabel(name)
        lb.setStyleSheet('font-weight:bold; font-size:%dpx; color:%s; background:%s;'
                         'padding:1px 6px;' % (sz(12), '#0A0A0C', C_YEL))
        head.addWidget(lb)
        self.cmb = QtWidgets.QComboBox()
        self.cmb.setEditable(True)
        self.cmb.addItems(CAM_TOPICS)
        if topic:
            self.cmb.setEditText(topic)
        head.addWidget(self.cmb, 1)
        b = ChipButton(u'订', 'ghost', 6)
        b.setFixedWidth(40)
        b.setMinimumHeight(24)
        b.clicked.connect(lambda: self.subscribe(self.cmb.currentText().strip()))
        head.addWidget(b)
        v.addLayout(head)

        self.view = QtWidgets.QLabel(u'// NO SIGNAL //  %s' % name)
        self.view.setAlignment(QtCore.Qt.AlignCenter)
        self.view.setMinimumSize(148, 98)
        self.view.setStyleSheet(
            'background:#07080A; color:#4A5158; border:1px solid %s;'
            'font-family:"%s"; font-size:%dpx;' % (C_LINE2, F_MONO, sz(10)))
        v.addWidget(self.view, 1)

        self.info = QtWidgets.QLabel(u'IDLE')
        self.info.setStyleSheet('color:%s; font-family:"%s"; font-size:%dpx;' % (C_TX2, F_MONO, sz(10)))
        v.addWidget(self.info)

    def subscribe(self, topic=None):
        if not HAS_CV:
            self.info.setText(u'NO CV2')
            return
        if not topic:
            topic = self.cmb.currentText().strip()
        if not topic:
            return
        if self.sub is not None:
            try:
                self.sub.unregister()
            except Exception:
                pass
            self.sub = None
        try:
            self.topic = topic
            self.frames = 0
            self.last_ts = 0.0
            self.sub = rospy.Subscriber(topic, CompressedImage, self.on_image,
                                        queue_size=1, buff_size=2 ** 24)
            self.info.setText(u'WAIT %s' % topic)
        except Exception as e:
            self.info.setText(u'ERR %s' % str(e)[:30])

    def on_image(self, msg):
        try:
            buf = np.frombuffer(msg.data, dtype=np.uint8)
            # ★ 按显示尺寸选自适应降采样解码：5120x720 全景全彩解码是最大 CPU 开销，
            #   降 2/4 倍解码可省约 4/16 倍像素运算，肉眼几乎无差别
            tw = max(180, self.view.width())
            if self._src_w > tw * 3:
                flag, red = cv2.IMREAD_REDUCED_COLOR_4, 4
            elif self._src_w > tw * 1.8:
                flag, red = cv2.IMREAD_REDUCED_COLOR_2, 2
            else:
                flag, red = cv2.IMREAD_COLOR, 1
            img = cv2.imdecode(buf, flag)
            if img is None:
                return
            h, w = img.shape[:2]
            self._src_w = w * red
            # ★ 四合一全景按需只取其中一路（crop 为 (起, 止) 比例）
            if self.crop:
                x0 = max(0, int(w * self.crop[0]))
                x1 = min(w, int(w * self.crop[1]))
                if x1 > x0:
                    img = img[:, x0:x1]
                    h, w = img.shape[:2]
            self.frames += 1
            self.size_txt = '%dx%d' % (w, h)
            maxw = max(180, self.view.width() - 4)
            maxh = max(110, self.view.height() - 4)
            sc = min(float(maxw) / w, float(maxh) / h)
            if sc < 1.0:
                img = cv2.resize(img, (max(1, int(w * sc)), max(1, int(h * sc))))
                h, w = img.shape[:2]
            rgb = cv2.cvtColor(img, cv2.COLOR_BGR2RGB)
            q = QtGui.QImage(rgb.data, w, h, rgb.strides[0], QtGui.QImage.Format_RGB888).copy()
            self._rgb = rgb
            self._pix = QtGui.QPixmap.fromImage(q)
            self.view.setPixmap(self._pix)
        except Exception:
            pass

    def tick(self):
        if not self.topic:
            return
        now = time.time()
        if self.last_ts > 0:
            fps = self.frames / max(0.001, now - self.last_ts)
            if self.frames > 0:
                self.info.setText(u'■ LIVE  %.1f FPS  %s' % (fps, self.size_txt))
                self.info.setStyleSheet('color:%s; font-family:"%s"; font-size:%dpx;'
                                        % (C_OK, F_MONO, sz(10)))
            else:
                self.info.setText(u'□ NO SIGNAL  %s' % self.size_txt)
                self.info.setStyleSheet('color:%s; font-family:"%s"; font-size:%dpx;'
                                        % (C_RED, F_MONO, sz(10)))
        self.frames = 0
        self.last_ts = now


