class CalibStatus(QtCore.QThread):
    line = QtCore.pyqtSignal(str)

    def run(self):
        cwd = os.path.join(CALIB_DIR, 'camera_dist_calib')
        self.line.emit(u'—— 本地（%s）——' % cwd)
        try:
            out = subprocess.check_output(
                ['bash', '-c', "cd '%s' && ls -la --time-style=long-iso calib_*.yaml image_*.jpg 2>/dev/null" % cwd])
            for ln in out.splitlines():
                self.line.emit(u'  ' + ln.decode('utf-8', 'ignore'))
        except Exception as e:
            self.line.emit(u'  （读取失败: %s）' % str(e)[:60])
        self.line.emit(u'—— 车机 /work/share/project/data/ ——')
        try:
            out = subprocess.check_output(
                ['bash', '-c',
                 "sshpass -p idriver_bbox ssh -o StrictHostKeyChecking=no "
                 "-o UserKnownHostsFile=/dev/null -o ConnectTimeout=8 -o LogLevel=ERROR "
                 "nvidia@192.168.1.103 \"ls -la --time-style=long-iso "
                 "/work/share/project/data/*.yaml\" 2>/dev/null"])
            txt = out.strip()
            if not txt:
                self.line.emit(u'  （车机无标定文件或不可达）')
            for ln in txt.splitlines():
                self.line.emit(u'  ' + ln.decode('utf-8', 'ignore'))
        except Exception as e:
            self.line.emit(u'  （车机不可达: %s）' % str(e)[:60])



