        super(Console, self).__init__()
        self.setWindowTitle(u'多传感器+线控底盘一体化融合标定软件')
        # --- 响应式：初始尺寸按屏幕可用区自适应并居中（小屏不顶出屏幕）---
        try:
            scr = QtWidgets.QApplication.primaryScreen().availableGeometry()
            w = max(1100, min(1560, int(scr.width() * 0.94)))
            h = max(700, min(960, int(scr.height() * 0.94)))
            self.resize(w, h)
            self.move(scr.x() + max(0, (scr.width() - w) // 2),
                      scr.y() + max(0, (scr.height() - h) // 2))
        except Exception:
            self.resize(1400, 880)
        self.setMinimumSize(1080, 680)
        self.setStyleSheet(qss())
        self.sig_ui.connect(self._run_ui)
        self.holder = {'client': None, 'node': None}
        self.worker = CmdWorker(self.holder)
        self.worker.done.connect(self.on_cmd_done)
        self.probe = ProbeWorker()
        self.probe.line.connect(self.append_log)
